        ['id' => 82101, 'event_id' => 821, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Before you test</h3><p><img src="{{media:40}}" width="520" alt=""></p><p>The pH scale runs from 0 to 14. Pure water is 7.</p><p>If a test strip reads <strong>3</strong>, what does that tell you about the water?</p>', 'call_to_actions' => [['text' => 'It is strongly acidic', 'action' => ['type' => 'run_event', 'target_event_id' => 822]], ['text' => 'It is neutral, like pure water', 'action' => ['type' => 'run_event', 'target_event_id' => 823]], ['text' => 'It is a strong base', 'action' => ['type' => 'run_event', 'target_event_id' => 824]]], 'dismissible' => false]],
