        ['id' => 82302, 'event_id' => 823, 'type' => 'infobox', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Not quite</h3><p>Neutral is exactly 7. A reading of 3 is well below that, which makes it a fairly strong <strong>acid</strong>.</p>']],
        ['id' => 82401, 'event_id' => 824, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_ph', 'operator' => 'set', 'operand' => 'c']],
        ['id' => 82402, 'event_id' => 824, 'type' => 'infobox', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Not quite</h3><p>Bases are the numbers <strong>above</strong> 7. A reading of 3 is below 7, which makes it an <strong>acid</strong>.</p>']],
