        ['id' => 83801, 'event_id' => 838, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'scope_meadow', 'operator' => 'set', 'operand' => 'plump green cells, nothing unusual']],
        ['id' => 83802, 'event_id' => 838, 'type' => 'variable', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'scope_tests', 'operator' => '+', 'operand' => 1]],
        ['id' => 83803, 'event_id' => 838, 'type' => 'variable', 'sequence' => 3, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'tests_done', 'operator' => '+', 'operand' => 1]],
        ['id' => 83804, 'event_id' => 838, 'type' => 'infobox', 'sequence' => 4, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Meadow sample</h3><p><img src="{{media:44}}" width="300" alt=""></p><p>The cells are <strong>plump and green</strong>, packed neatly together, with intact walls. Nothing unusual.</p>']],
        ['id' => 83101, 'event_id' => 831, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>What does the evidence say?</h3><p>The sick plants have damaged cells, but you found <strong>no fungus and no bacteria</strong> in any sample.</p><p>What is the best conclusion?</p>', 'call_to_actions' => [['text' => 'The plants caught an infection that spreads from plant to plant', 'action' => ['type' => 'run_event', 'target_event_id' => 832]], ['text' => 'Something in their surroundings is damaging them', 'action' => ['type' => 'run_event', 'target_event_id' => 833]], ['text' => 'The microscope must be broken', 'action' => ['type' => 'run_event', 'target_event_id' => 834]]], 'dismissible' => false]],
        ['id' => 83201, 'event_id' => 832, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_cells', 'operator' => 'set', 'operand' => 'a']],
        ['id' => 83202, 'event_id' => 832, 'type' => 'infobox', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Not quite</h3><p>An infection is caused by living things such as fungus or bacteria, and you would expect to see them. You found none, so the evidence points away from infection and toward something in the plants\' <strong>surroundings</strong>.</p>']],
        ['id' => 83301, 'event_id' => 833, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_cells', 'operator' => 'set', 'operand' => 'b']],
        ['id' => 83302, 'event_id' => 833, 'type' => 'variable', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'science_score', 'operator' => '+', 'operand' => 1]],
        ['id' => 83303, 'event_id' => 833, 'type' => 'infobox', 'sequence' => 3, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Correct!</h3><p>Yes. With no microbes present, an infection is unlikely. The damage is more likely caused by something in the <strong>environment</strong>, such as the water the plants are growing in.</p>']],
        ['id' => 83401, 'event_id' => 834, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_cells', 'operator' => 'set', 'operand' => 'c']],
        ['id' => 83402, 'event_id' => 834, 'type' => 'infobox', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Not quite</h3><p>The microscope showed the healthy sample perfectly well, so it works. The evidence is real: no microbes, which points toward something in the plants\' <strong>surroundings</strong>.</p>']],
        ['id' => 84101, 'event_id' => 841, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Make a prediction</h3><p>The beaker holds stream water from the gully. It is acidic.</p><p>What should you add to bring it back toward neutral (pH 7)?</p>', 'call_to_actions' => [['text' => 'An acid, such as lemon juice', 'action' => ['type' => 'run_event', 'target_event_id' => 842]], ['text' => 'A base, such as baking soda', 'action' => ['type' => 'run_event', 'target_event_id' => 843]], ['text' => 'Table salt', 'action' => ['type' => 'run_event', 'target_event_id' => 844]]], 'dismissible' => false]],
        ['id' => 84201, 'event_id' => 842, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_base', 'operator' => 'set', 'operand' => 'a']],
        ['id' => 84202, 'event_id' => 842, 'type' => 'infobox', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Not quite</h3><p>Adding an acid makes water <em>more</em> acidic, so the pH goes down. A <strong>base</strong> does the opposite and cancels acid out. Try both and watch the number.</p>']],
        ['id' => 84301, 'event_id' => 843, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_base', 'operator' => 'set', 'operand' => 'b']],
        ['id' => 84302, 'event_id' => 843, 'type' => 'variable', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'science_score', 'operator' => '+', 'operand' => 1]],
        ['id' => 84303, 'event_id' => 843, 'type' => 'infobox', 'sequence' => 3, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Correct!</h3><p>Right. A <strong>base</strong> cancels out an acid. Scientists call this <strong>neutralising</strong>. Now test your prediction.</p>']],
        ['id' => 84401, 'event_id' => 844, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_base', 'operator' => 'set', 'operand' => 'c']],
        ['id' => 84402, 'event_id' => 844, 'type' => 'infobox', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Not quite</h3><p>Salt dissolves but does not change the pH. A <strong>base</strong>, such as baking soda, cancels out an acid. Try it and watch the number.</p>']],
        ['id' => 84501, 'event_id' => 845, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Mixing bench</h3><p><img src="{{media:40}}" width="520" alt=""></p><p>The beaker of gully water now reads <strong>pH {{beaker_ph}}</strong>.</p><p>Add one drop at a time and watch what happens to the number.</p>', 'call_to_actions' => [['text' => 'Add a drop of baking soda solution (a base)', 'action' => ['type' => 'variable', 'name' => 'beaker_ph', 'operator' => '+', 'operand' => 1], 'conditions' => [['variable' => 'beaker_ph', 'operator' => '<', 'operand' => 14]]], ['text' => 'Add a drop of lemon juice (an acid)', 'action' => ['type' => 'variable', 'name' => 'beaker_ph', 'operator' => '-', 'operand' => 1], 'conditions' => [['variable' => 'beaker_ph', 'operator' => '>', 'operand' => 0]]], ['text' => 'Step away', 'action' => ['type' => 'variable', 'name' => 'beaker_done', 'operator' => 'set', 'operand' => 1]]], 'dismissible' => false]],
        ['id' => 84502, 'event_id' => 845, 'type' => 'infobox', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Neutral!</h3><p>The beaker reads <strong>pH 7</strong>. Each drop of base cancelled out some of the acid. If the leak were stopped, the stream could recover in the same way.</p>']],
